-- Read-only catalog manifest: no customer rows or credentials.
select jsonb_build_object(
'functions',(select jsonb_agg(jsonb_build_object('signature',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')','hash',md5(regexp_replace(pg_get_functiondef(p.oid),'[[:space:]]','','g')),'anon',has_function_privilege('anon',p.oid,'execute'),'authenticated',has_function_privilege('authenticated',p.oid,'execute')) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('private','public') and p.prokind='f' and p.proname !~ '^uuid_'),
'columns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'nullable',is_nullable,'default',column_default) order by table_name,ordinal_position) from information_schema.columns where table_schema='public' and table_name in ('shops','shop_image_assets','r2_media_objects','invoice_logo_assets','daily_note_attachments')),
'constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',co.conname,'definition',pg_get_constraintdef(co.oid)) order by c.relname,co.conname) from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('shops','shop_image_assets','r2_media_objects','invoice_logo_assets','daily_note_attachments')),
'rls',(select jsonb_agg(jsonb_build_object('table',c.relname,'enabled',c.relrowsecurity,'forced',c.relforcerowsecurity,'anon_read',has_table_privilege('anon',c.oid,'select'),'auth_read',has_table_privilege('authenticated',c.oid,'select'),'auth_write',has_table_privilege('authenticated',c.oid,'insert')) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('shop_image_assets','r2_media_objects','invoice_logo_assets','daily_note_attachments')),
'storage_insert_policies',(select jsonb_agg(policyname order by policyname) from pg_policies where schemaname='storage' and tablename='objects' and cmd='INSERT')
) as manifest;
